package com.hbm.satellite.link.client;
import com.hbm.client.model.*;import com.hbm.satellite.link.*;import com.hbm.multiblock.DummyableBlock;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;import org.joml.Matrix4f;
/** Exact RenderSatLink source noSmooth geometry, metadata center offset, Rotor/Dish animation and7.375 pivot. */
public final class SatelliteLinkRenderer implements BlockEntityRenderer<SatelliteLinkBlockEntity>{
 public SatelliteLinkRenderer(BlockEntityRendererProvider.Context context){}static WavefrontMesh mesh(){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:models/machines/satlink.obj"));}static void part(String name,PoseStack poses,MultiBufferSource buffers,int light,int overlay){LegacyObjRenderer.renderOnly(mesh(),poses,buffers.getBuffer(RenderType.entityCutout(ResourceLocation.parse("hbm:textures/models/machines/satlink.png"))),light,overlay,-1,LegacyObjRenderer.Convention.HFR_FLAT,name);}
 @Override public void render(SatelliteLinkBlockEntity link,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){var facing=DummyableBlock.facing(link.getBlockState());var rot=facing.getCounterClockWise();float x=(facing.getStepX()+rot.getStepX())*.5F,z=(facing.getStepZ()+rot.getStepZ())*.5F;LegacyContactShadows.render(link,mesh(),new Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.PI).translate(x,0,z),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(180));poses.translate(x,0,z);part("Base",poses,buffers,light,overlay);poses.mulPose(Axis.YP.rotationDegrees(link.prevRot+(link.rot-link.prevRot)*partial));part("Rotor",poses,buffers,light,overlay);poses.translate(0,7.375,0);poses.mulPose(Axis.ZP.rotationDegrees(link.prevLift+(link.lift-link.prevLift)*partial));poses.translate(0,-7.375,0);part("Dish",poses,buffers,light,overlay);poses.popPose();}@Override public boolean shouldRenderOffScreen(SatelliteLinkBlockEntity link){return true;}@Override public int getViewDistance(){return 256;}@Override public AABB getRenderBoundingBox(SatelliteLinkBlockEntity link){var p=link.getBlockPos();return new AABB(p.getX()-2,p.getY(),p.getZ()-2,p.getX()+3,p.getY()+10,p.getZ()+3);}
}
